<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import { Check, ChevronDown, ImagePlus, Search, Settings2, Sparkles, Trash2, Upload, WandSparkles, X } from "@lucide/vue";
import { api, bestEffort, formatNumber, json, timeAgo } from "../api";
import type { StickerAsset } from "../types";
import EmptyState from "./EmptyState.vue";

const emit = defineEmits<{ notify: [tone:"success"|"error"|"info", title:string, detail?:string] }>();
const items = ref<StickerAsset[]>([]); const stats = ref<Record<string,number>>({}); const categories = ref<string[]>([]); const selected = ref(new Set<string>()); const loading = ref(true);
const query = ref(""); const status = ref(""); const category = ref(""); const scope = ref(""); const sort = ref("newest"); const view = ref<"pending"|"library">("pending");
const uploadOpen = ref(false); const policyOpen = ref(false); const batchOpen = ref(false); const files = ref<File[]>([]); const uploadCategory = ref(""); const uploadScope = ref("local"); const uploading = ref(false);
const editCategory = ref(""); const editScope = ref(""); const policy = ref<Record<string,any>>({});
let timer:number|undefined;

const shown = computed(() => view.value === "pending" ? items.value.filter(i=>i.status==="pending_review") : items.value.filter(i=>i.status!=="pending_review"));
const allSelected = computed(() => shown.value.length > 0 && shown.value.every(item=>selected.value.has(item.id)));
const selectedCount = computed(() => selected.value.size);

async function load(){loading.value=true;try{const params=new URLSearchParams({q:query.value,status:status.value,category:category.value,scope:scope.value,sort:sort.value});const [assets,policyData]=await Promise.all([bestEffort(api<any>(`/api/stickers/assets?${params}`),{items:[],stats:{},categories:[]}),bestEffort(api<any>("/api/stickers/policy"),{})]);items.value=assets.items||[];stats.value=assets.stats||{};categories.value=assets.categories||[];policy.value=policyData;}finally{loading.value=false}}
watch([query,status,category,scope,sort],()=>{window.clearTimeout(timer);timer=window.setTimeout(load,260)});
function toggle(id:string){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
function toggleAll(){selected.value=allSelected.value?new Set():new Set(shown.value.map(i=>i.id))}
async function batch(action:string, extra:Record<string,any>={}){if(!selectedCount.value)return;try{const result=await api<any>("/api/stickers/batch",json("POST",{ids:[...selected.value],action,...extra}));emit("notify","success",`已处理 ${result.changed} 张表情`);selected.value=new Set();batchOpen.value=false;await load();}catch(e:any){emit("notify","error","批量操作失败",e.message)}}
async function approveOne(item:StickerAsset){selected.value=new Set([item.id]);await batch("approve")}
async function rejectOne(item:StickerAsset){try{await api(`/api/stickers/${item.id}/reject`,json("POST",{}));emit("notify","success","已拒绝这张表情");await load()}catch(e:any){emit("notify","error","拒绝失败",e.message)}}
function chooseFiles(event:Event){files.value=Array.from((event.target as HTMLInputElement).files||[])}
async function upload(){if(!files.value.length)return;uploading.value=true;try{const body=new FormData();files.value.forEach(file=>body.append("files",file));body.append("category",uploadCategory.value);body.append("scope",uploadScope.value);body.append("auto_analyze","true");const result=await api<any>("/api/stickers/import",{method:"POST",body});emit("notify","success",`导入完成：新增 ${result.added||0} 张`,`跳过 ${result.skipped||0}，拒绝 ${result.rejected||0}`);uploadOpen.value=false;files.value=[];await load();}catch(e:any){emit("notify","error","上传失败",e.message)}finally{uploading.value=false}}
async function savePolicy(){try{await api("/api/stickers/policy",json("POST",policy.value));emit("notify","success","表情策略已保存");policyOpen.value=false;}catch(e:any){emit("notify","error","策略保存失败",e.message)}}
async function maintenance(kind:"maintenance"|"reclassify"){try{emit("notify","info",kind==="maintenance"?"正在维护索引":"正在让 LLM 重审全库");const result=await api<any>(`/api/stickers/${kind}`,json("POST",{}));emit("notify","success",kind==="maintenance"?"索引维护完成":"LLM 重审完成",Object.entries(result).map(([k,v])=>`${k} ${v}`).join(" · "));await load();}catch(e:any){emit("notify","error","操作失败",e.message)}}
function statusName(value:string){return ({pending_review:"待审核",approved:"可发送",rejected:"已拒绝"} as Record<string,string>)[value]||value}
onMounted(load);
</script>

<template><div class="sticker-manager">
  <div class="sticker-command panel">
    <div class="sticker-tabs"><button :class="{active:view==='pending'}" @click="view='pending'">审核池 <span>{{ stats.pending_review||0 }}</span></button><button :class="{active:view==='library'}" @click="view='library'">表情库 <span>{{ stats.count||0 }}</span></button></div>
    <div class="sticker-actions"><button class="action-button subtle" @click="policyOpen=true"><Settings2 :size="16"/>收集策略</button><button class="action-button" @click="uploadOpen=true"><Upload :size="16"/>上传表情</button></div>
  </div>
  <div class="asset-overview"><article><span>{{ formatNumber(stats.count) }}</span><small>库内资产</small></article><article><span>{{ formatNumber(stats.approved) }}</span><small>可发送</small></article><article><span>{{ formatNumber(stats.pending_review) }}</span><small>等待判断</small></article><article><span>{{ formatNumber(stats.total_collected) }}</span><small>历史收集</small></article><div class="capacity"><span><i :style="{width:`${Math.min(100,Number(stats.count||0)/Math.max(1,Number(stats.max_stickers||1))*100)}%`}"/></span><small>容量 {{ formatNumber(stats.count) }} / {{ formatNumber(stats.max_stickers) }}</small></div></div>
  <div class="asset-toolbar panel">
    <label class="asset-search"><Search :size="16"/><input v-model="query" aria-label="搜索表情" placeholder="搜索情绪、场景或标签"/></label>
    <select v-model="status" aria-label="审核状态"><option value="">全部状态</option><option value="pending_review">待审核</option><option value="approved">可发送</option><option value="rejected">已拒绝</option></select>
    <select v-model="category" aria-label="分类"><option value="">全部分类</option><option v-for="item in categories" :key="item">{{ item }}</option></select>
    <select v-model="scope" aria-label="作用域"><option value="">全部作用域</option><option value="local">来源群</option><option value="public">公共</option></select>
    <select v-model="sort" aria-label="排序"><option value="newest">最新收集</option><option value="oldest">最早收集</option><option value="used">最常使用</option><option value="recent_used">最近使用</option><option value="emotion">按情绪</option></select>
    <button class="select-all" @click="toggleAll"><span :class="{checked:allSelected}"><Check v-if="allSelected" :size="13"/></span>{{ allSelected?'取消全选':'全选当前' }}</button>
  </div>
  <div v-if="loading" class="asset-grid"><div v-for="n in 8" :key="n" class="asset-card skeleton"/></div>
  <div v-else-if="shown.length" class="asset-grid">
    <article v-for="item in shown" :key="item.id" class="asset-card" :class="{selected:selected.has(item.id)}">
      <button class="asset-check" :aria-label="selected.has(item.id)?'取消选择':'选择表情'" @click="toggle(item.id)"><Check v-if="selected.has(item.id)" :size="14"/></button>
      <div class="asset-image"><img :src="`/api/stickers/${item.id}/image`" loading="lazy" :alt="`${item.emotion||item.category} 表情包`"/><span class="asset-status" :class="item.status">{{ statusName(item.status) }}</span></div>
      <div class="asset-copy"><div><strong>{{ item.emotion||'未识别情绪' }}</strong><span>{{ item.scope==='public'?'公共':'群 '+(item.source_group||'未知') }}</span></div><p>{{ item.category||'未分类' }} · 使用 {{ item.used }} 次 · {{ timeAgo(item.created_at) }}</p><div class="asset-labels"><span v-for="label in item.labels.slice(0,4)" :key="label">{{ label }}</span><em v-if="item.is_sticker===false">疑似普通图片</em></div></div>
      <div v-if="item.status==='pending_review'" class="asset-review"><button @click="rejectOne(item)"><X :size="15"/>拒绝</button><button @click="approveOne(item)"><Check :size="15"/>收进图库</button></div>
    </article>
  </div>
  <EmptyState v-else :title="view==='pending'?'审核池已经清空':'没有找到表情'" :detail="view==='pending'?'新的群聊图片会先由 LLM 判断，再来到这里等你确认。':'尝试清空筛选条件，或上传新的表情资产。'"><button v-if="view==='library'" class="action-button" @click="uploadOpen=true"><ImagePlus :size="16"/>上传第一批</button></EmptyState>
  <div v-if="selectedCount" class="batch-dock"><span><b>{{ selectedCount }}</b> 张已选择</span><button @click="batch('approve')"><Check :size="16"/>批准</button><button @click="batchOpen=true"><WandSparkles :size="16"/>改分类/范围</button><button class="danger" @click="batch('delete')"><Trash2 :size="16"/>删除</button><button class="icon-button" @click="selected=new Set()"><X :size="17"/></button></div>

  <div v-if="uploadOpen" class="modal-backdrop" @click.self="uploadOpen=false"><section class="modal"><header class="modal-head"><Upload :size="19"/><strong>上传并交给 LLM 审核</strong><button class="icon-button" @click="uploadOpen=false"><X :size="18"/></button></header><div class="modal-body upload-body"><label class="drop-zone"><input type="file" multiple accept="image/*" @change="chooseFiles"/><ImagePlus :size="27"/><strong>{{ files.length?`已选择 ${files.length} 张`:'选择或拖入图片' }}</strong><span>支持常见图片与 GIF；不会上传聊天上下文。</span></label><div class="upload-fields"><label class="field"><span class="field-label">初始分类</span><input v-model="uploadCategory" placeholder="留空让 LLM 判断"/></label><label class="field"><span class="field-label">作用域</span><select v-model="uploadScope"><option value="local">来源群（默认）</option><option value="public">全部允许群</option></select></label></div></div><footer class="modal-foot"><button class="action-button subtle" @click="uploadOpen=false">取消</button><button class="action-button" :disabled="!files.length||uploading" @click="upload"><Sparkles :size="16"/>{{ uploading?'正在识别…':'上传并审核' }}</button></footer></section></div>
  <div v-if="policyOpen" class="modal-backdrop" @click.self="policyOpen=false"><section class="modal"><header class="modal-head"><Settings2 :size="19"/><strong>收集与发送策略</strong><button class="icon-button" @click="policyOpen=false"><X :size="18"/></button></header><div class="modal-body policy-fields"><label class="field"><span class="field-label">收集模式</span><select v-model="policy.collect_mode"><option value="cooldown">冷却后收集</option><option value="probability">按概率收集</option></select></label><label class="field"><span class="field-label">收集概率</span><input v-model.number="policy.collect_probability" type="number" min="0" max="1" step="0.01"/></label><label class="field"><span class="field-label">发送概率</span><input v-model.number="policy.send_probability" type="number" min="0" max="1" step="0.01"/></label><label class="field"><span class="field-label">待审池容量</span><input v-model.number="policy.pending_capacity" type="number" min="1"/></label><label class="field"><span class="field-label">默认作用域</span><select v-model="policy.default_scope"><option value="local">来源群</option><option value="public">公共</option></select></label><div class="policy-tools"><button class="action-button subtle" @click="maintenance('maintenance')">维护索引</button><button class="action-button subtle" @click="maintenance('reclassify')"><Sparkles :size="15"/>LLM 重审全库</button></div></div><footer class="modal-foot"><button class="action-button subtle" @click="policyOpen=false">取消</button><button class="action-button" @click="savePolicy">保存策略</button></footer></section></div>
  <div v-if="batchOpen" class="modal-backdrop" @click.self="batchOpen=false"><section class="modal batch-modal"><header class="modal-head"><WandSparkles :size="19"/><strong>整理 {{ selectedCount }} 张表情</strong><button class="icon-button" @click="batchOpen=false"><X :size="18"/></button></header><div class="modal-body upload-fields"><label class="field"><span class="field-label">新分类</span><input v-model="editCategory" placeholder="例如：开心 / 嫌弃 / 震惊"/></label><label class="field"><span class="field-label">作用域</span><select v-model="editScope"><option value="">保持不变</option><option value="local">来源群</option><option value="public">公共</option></select></label></div><footer class="modal-foot"><button class="action-button subtle" @click="batchOpen=false">取消</button><button class="action-button" @click="batch('edit',{category:editCategory||undefined,scope:editScope||undefined})">应用修改</button></footer></section></div>
</div></template>

<style scoped>
.sticker-command{min-height:68px;display:flex;align-items:center;justify-content:space-between;padding:10px 12px 10px 18px}.sticker-tabs{display:flex;align-self:stretch;gap:22px}.sticker-tabs button{position:relative;border:0;background:transparent;color:var(--muted);font-weight:700;font-size:12px;cursor:pointer}.sticker-tabs button span{margin-left:5px;color:#746a7b;font-size:var(--fs-sm)}.sticker-tabs button.active{color:var(--ink)}.sticker-tabs button.active::after{content:"";position:absolute;left:0;right:0;bottom:-10px;height:2px;background:var(--lime)}.sticker-tabs button.active span{color:var(--lime)}.sticker-actions{display:flex;gap:8px}.asset-overview{display:grid;grid-template-columns:repeat(4,120px) 1fr;gap:1px;margin-top:12px;border-block:1px solid var(--line);background:var(--line)}.asset-overview article,.capacity{padding:14px 16px;background:rgba(16,13,23,.86)}.asset-overview span,.asset-overview small{display:block}.asset-overview article span{font:720 18px Georgia,serif;color:var(--lime)}.asset-overview small{margin-top:4px;color:var(--muted);font-size:var(--fs-xs)}.capacity{display:flex;align-items:center;gap:12px}.capacity>span{height:4px;flex:1;background:rgba(255,255,255,.07)}.capacity i{display:block;height:100%;background:linear-gradient(90deg,var(--lime),var(--pink))}.capacity small{white-space:nowrap}.asset-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) repeat(4,minmax(115px,auto)) auto;gap:8px;margin-top:12px;padding:10px}.asset-search{min-height:42px;display:flex;align-items:center;gap:8px;padding:0 11px;border:1px solid var(--line-strong);background:rgba(8,7,13,.45)}.asset-search svg{color:var(--muted)}.asset-search input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:var(--ink);font-size:var(--fs-sm)}.asset-toolbar select{min-height:42px;padding:0 9px;border:1px solid var(--line);background:#15111d;color:var(--ink-soft);font-size:var(--fs-sm)}.select-all{min-height:42px;border:0;background:transparent;color:var(--muted);display:flex;align-items:center;gap:7px;font-size:var(--fs-sm);cursor:pointer}.select-all>span{width:17px;height:17px;display:grid;place-items:center;border:1px solid var(--line-strong)}.select-all>span.checked{background:var(--lime);color:#17210f;border-color:var(--lime)}.asset-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:10px;margin-top:12px}.asset-card{position:relative;min-height:310px;border:1px solid var(--line);background:rgba(24,20,34,.86);overflow:hidden;transition:transform 200ms var(--ease-out),border-color 200ms,box-shadow 200ms}.asset-card:hover{transform:translateY(-3px);border-color:rgba(196,246,110,.25);box-shadow:var(--shadow-md)}.asset-card.selected{border-color:var(--lime);box-shadow:0 0 0 1px var(--lime)}.asset-image{position:relative;aspect-ratio:1.25;background:#0b0910;display:grid;place-items:center;overflow:hidden}.asset-image img{width:100%;height:100%;object-fit:contain;transition:transform 300ms var(--ease-out)}.asset-card:hover img{transform:scale(1.025)}.asset-check{position:absolute;z-index:3;left:9px;top:9px;width:28px;height:28px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.25);background:rgba(8,7,13,.72);color:#17210f;cursor:pointer}.asset-card.selected .asset-check{background:var(--lime);border-color:var(--lime)}.asset-status{position:absolute;right:8px;top:8px;padding:5px 7px;background:rgba(10,8,14,.75);backdrop-filter:blur(8px);font-size:var(--fs-xs)}.asset-status.pending_review{color:var(--amber)}.asset-status.approved{color:var(--lime)}.asset-status.rejected{color:var(--red)}.asset-copy{padding:13px}.asset-copy>div:first-child{display:flex;justify-content:space-between;gap:8px}.asset-copy strong{font-size:11px}.asset-copy>div:first-child span{color:var(--muted);font-size:var(--fs-xs)}.asset-copy p{margin:5px 0 9px;color:var(--muted);font-size:var(--fs-xs)}.asset-labels{display:flex;gap:4px;flex-wrap:wrap}.asset-labels span,.asset-labels em{padding:4px 6px;background:rgba(255,255,255,.055);color:var(--ink-soft);font:normal var(--fs-xs) ui-monospace,monospace}.asset-labels em{color:var(--red);background:rgba(255,123,133,.08)}.asset-review{display:grid;grid-template-columns:1fr 1.4fr;border-top:1px solid var(--line)}.asset-review button{min-height:42px;border:0;border-right:1px solid var(--line);background:transparent;color:var(--muted);font-size:var(--fs-sm);display:flex;align-items:center;justify-content:center;gap:6px;cursor:pointer}.asset-review button:last-child{border:0;color:var(--lime)}.asset-review button:hover{background:rgba(255,255,255,.04)}.batch-dock{position:fixed;z-index:35;left:calc(270px + (100vw - 270px)/2);bottom:24px;transform:translateX(-50%);min-height:58px;padding:8px 9px 8px 17px;display:flex;align-items:center;gap:6px;border:1px solid rgba(196,246,110,.25);background:rgba(24,20,34,.96);box-shadow:var(--shadow-md);backdrop-filter:blur(18px);animation:dock-in 300ms var(--ease-snap)}@keyframes dock-in{from{opacity:0;transform:translate(-50%,12px)}}.batch-dock>span{margin-right:8px;font-size:var(--fs-sm)}.batch-dock>span b{color:var(--lime)}.batch-dock>button:not(.icon-button){min-height:39px;border:0;padding:0 11px;background:rgba(255,255,255,.06);color:var(--ink-soft);display:flex;align-items:center;gap:6px;font-size:var(--fs-sm);cursor:pointer}.batch-dock>button.danger{color:var(--red)}.upload-body{display:grid;gap:17px}.drop-zone{min-height:190px;border:1px dashed rgba(196,246,110,.35);background:rgba(196,246,110,.035);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;cursor:pointer}.drop-zone input{position:absolute;opacity:0;pointer-events:none}.drop-zone svg{color:var(--lime)}.drop-zone strong{font-size:12px}.drop-zone span{color:var(--muted);font-size:var(--fs-sm)}.upload-fields,.policy-fields{display:grid;grid-template-columns:1fr 1fr;gap:13px}.policy-tools{grid-column:1/-1;display:flex;gap:8px;padding-top:10px}.batch-modal{max-width:510px}@media(max-width:1200px){.asset-toolbar{grid-template-columns:1fr 1fr 1fr}.asset-search{grid-column:span 2}.asset-overview{grid-template-columns:repeat(4,1fr)}.capacity{grid-column:1/-1}}@media(max-width:1023px){.batch-dock{left:50%}}@media(max-width:700px){.sticker-command{align-items:stretch;gap:13px;flex-direction:column}.sticker-tabs{min-height:46px}.sticker-actions{display:grid;grid-template-columns:1fr 1fr}.asset-overview{grid-template-columns:1fr 1fr}.asset-toolbar{grid-template-columns:1fr 1fr}.asset-search{grid-column:1/-1}.asset-toolbar select{min-width:0}.asset-grid{grid-template-columns:1fr 1fr}.batch-dock{bottom:84px;width:calc(100vw - 20px);overflow-x:auto}.batch-dock>span{white-space:nowrap}.upload-fields,.policy-fields{grid-template-columns:1fr}.policy-tools{grid-column:auto}}@media(max-width:480px){.asset-grid{grid-template-columns:1fr}.asset-card{min-height:auto}.asset-overview article{padding:12px}.asset-status{font-size:var(--fs-xs)}}
</style>
